/**
 * Replaces all segments in this instance, but keeps generation, version, counter so that future
 * commits remain write once.
 */
void replace(SegmentInfos other) {
  final List<SegmentCommitInfo> incoming = Collections.unmodifiableList(other.segments);
  this.segments.clear();

  final long incomingGeneration = other.lastGeneration;
  final String incomingSegmentsFile;
  if (incomingGeneration == 0) {
    incomingSegmentsFile = IndexFileNames.segmentFileName(IndexFileNames.SEGMENTS, "", "");
  } else {
    incomingSegmentsFile =
        IndexFileNames.fileNameFromGeneration(IndexFileNames.SEGMENTS, "", incomingGeneration);
  }

  for (int i = 0; i < incoming.size(); i++) {
    final SegmentCommitInfo commitInfo = incoming.get(i);
    final int maxDoc = commitInfo.segmentMaxDoc();
    final int delCount = commitInfo.getDelCount();
    final int softDelCount = commitInfo.getSoftDelCount();

    if (indexCreatedVersionMajor >= 7) {
      if (commitInfo.missingMinVersion()) {
        throw new IllegalArgumentException(
            "All segments must record the minVersion for indices created on or after Lucene 7");
      }
      if (commitInfo.writtenWithOlderMajor(indexCreatedVersionMajor)) {
        throw new IllegalArgumentException(
            "segments file recorded indexCreatedVersionMajor="
                + indexCreatedVersionMajor
                + " but segment="
                + commitInfo
                + " has older version");
      }
    }

    if (delCount < 0 || delCount > maxDoc) {
      if (commitInfo.hasDeletions()) {
        throw new IllegalStateException(
            "cannot replace segment from "
                + incomingSegmentsFile
                + ": invalid delCount="

    if (delCount < 0 || delCount > maxDoc) {
      if (commitInfo.hasDeletions()) {
        throw new IllegalStateException(
            "cannot replace segment from "
                + incomingSegmentsFile
                + ": invalid delCount="
                + delCount
                + " (maxDoc="
                + maxDoc
                + ", delGen="
                + commitInfo.getDelGen()
                + ")");
      } else {
        throw new IllegalStateException(
            "cannot replace segment from "
                + incomingSegmentsFile
                + ": invalid delCount="
                + delCount
                + " (maxDoc="
                + maxDoc
                + ")");
      }
    } else {
      if (softDelCount < 0 || softDelCount > maxDoc) {
        throw new IllegalStateException(
            "cannot replace segment from "
                + incomingSegmentsFile
                + ": invalid softDelCount="
                + softDelCount
                + " (maxDoc="
                + maxDoc
                + ")");
      } else {
        if (delCount + softDelCount > maxDoc) {
          throw new IllegalStateException(
              "cannot replace segment from "
                  + incomingSegmentsFile
                  + ": maxDoc="
                  + maxDoc
                  + ",delCount="
                  + delCount
                  + ",softDelCount="
                  + softDelCount);
        }
      }
    }

    for (Set<String> updateFiles : commitInfo.getDocValuesUpdatesFiles().values()) {
      for (String file : updateFiles) {
        String stripped = IndexFileNames.stripSegmentName(file);
        if (stripped.endsWith(".tmp")) {
          throw new IllegalArgumentException(
              "invalid codec filename '" + file + "', cannot end with .tmp extension");
        }
      }
    }

    this.segments.add(commitInfo);
  }

  lastGeneration = incomingGeneration;
}

/** Returns sum of all segment's maxDocs. Note that this does not include deletions */
public int totalMaxDoc() {
  long count = 0;
  for (SegmentCommitInfo info : this) {
    count += info.info.maxDoc();
  }
  // we should never hit this, checks should happen elsewhere...
  assert count <= IndexWriter.getActualMaxDocs();
  return Math.toIntExact(count);
}

/** Call this before committing if changes have been made to the segments. */
public void changed() {
  version++;
  // System.out.println(Thread.currentThread().getName() + ": SIS.change to version=" + version);
  // new Throwable().printStackTrace(System.out);
}

void setVersion(long newVersion) {
  if (newVersion < version) {
    throw new IllegalArgumentException(
        "newVersion (="
            + newVersion
            + ") cannot be less than current version (="
            + version
            + ")");
  }
  // System.out.println(Thread.currentThread().getName() + ": SIS.setVersion change from " +
  // version + " to " + newVersion);
  version = newVersion;
}

